            if (
                IERC1271(signer).isValidSignature(digest, signature) !=
                EIP1271_MAGICVALUE
            ) {
                return false;
            }
        } else {
            if (ECDSA.recover(digest, signature) != signer) {
                return false;
            }
        }
        return true;
    }
}

