        bytes calldata scriptPubkey,
        uint256 amount,
        uint64 fee,
        uint256 minAmount
    ) internal pure returns (uint256) {
        (
            uint256 amountAfterFee,
            bool isAboveFee,
            bool isAboveMinLimit
        ) = calcFeeAndDustLimit(scriptPubkey, amount, fee, minAmount);
