        if (!isAboveMinLimit) {
            revert AmountBelowMinLimit(minAmount);
        }

        return amountAfterFee;
    }

    function calcFeeAndDustLimit(
        bytes calldata scriptPubkey,
        uint256 amount,
        uint64 fee,
        uint256 minAmount
    ) internal pure returns (uint256, bool, bool) {
